"use client";

import {
  forwardRef,
  useCallback,
  useEffect,
  useId,
  useRef,
  useState,
  type CSSProperties,
  type KeyboardEvent,
  type PointerEvent,
  type ReactNode,
} from "react";
import { LayoutGroup, motion, useReducedMotion } from "framer-motion";
import { cn } from "@/lib/utils";
import { Popover } from "./Popover";
import { TextField } from "./TextField";

// Pick a colour. The field is a well with the colour sitting in a round socket; clicking it opens
// the picker on the Popover panel. Inside: a shade area cut into the panel, recessed hue and
// opacity tracks, a hex field, the screen eyedropper where the browser has one, and preset chips.
// Thumbs are rings filled with the colour they control; grabbing one lifts it a touch, letting go
// settles it. The preset matching the value is marked by a ring that glides between chips.
//
// Colour is kept as HSV internally, so a hue survives a trip through grey or black.

// ─── Colour helpers ─────────────────────────────────────────────────────────

export interface Hsva {
  /** 0–360 */
  h: number;
  /** 0–100 */
  s: number;
  /** 0–100 */
  v: number;
  /** 0–1 */
  a: number;
}

const clamp = (n: number, min = 0, max = 1) => Math.min(Math.max(n, min), max);

function hsvToRgb(h: number, s: number, v: number) {
  const S = s / 100;
  const V = v / 100;
  const k = (n: number) => (n + h / 60) % 6;
  const f = (n: number) => V - V * S * Math.max(0, Math.min(k(n), 4 - k(n), 1));
  return [f(5), f(3), f(1)].map((c) => Math.round(c * 255)) as [number, number, number];
}

function rgbToHsv(r: number, g: number, b: number) {
  const R = r / 255;
  const G = g / 255;
  const B = b / 255;
  const max = Math.max(R, G, B);
  const d = max - Math.min(R, G, B);
  let h = 0;
  if (d) {
    if (max === R) h = ((G - B) / d) % 6;
    else if (max === G) h = (B - R) / d + 2;
    else h = (R - G) / d + 4;
    h *= 60;
    if (h < 0) h += 360;
  }
  return { h, s: max ? (d / max) * 100 : 0, v: max * 100 };
}

/** "#4F7CFF", "4f7cff", "#47f", "#4F7CFF80" → HSVA, or null if it isn't a hex colour. */
export function hexToHsva(input: string): Hsva | null {
  let hex = input.trim().replace(/^#/, "");
  if (!/^([0-9a-f]{3,4}|[0-9a-f]{6}|[0-9a-f]{8})$/i.test(hex)) return null;
  if (hex.length <= 4) hex = hex.split("").map((c) => c + c).join("");
  const n = (i: number) => parseInt(hex.slice(i, i + 2), 16);
  const { h, s, v } = rgbToHsv(n(0), n(2), n(4));
  return { h, s, v, a: hex.length === 8 ? Math.round((n(6) / 255) * 100) / 100 : 1 };
}

/** HSVA → "#RRGGBB", or "#RRGGBBAA" when it's translucent (or `withAlpha` is set). */
export function hsvaToHex({ h, s, v, a }: Hsva, withAlpha = a < 1) {
  const hex = (n: number) => n.toString(16).padStart(2, "0");
  const [r, g, b] = hsvToRgb(h, s, v);
  return `#${hex(r)}${hex(g)}${hex(b)}${withAlpha ? hex(Math.round(clamp(a) * 255)) : ""}`.toUpperCase();
}

// ─── Component ──────────────────────────────────────────────────────────────

export type ColorPickerSize = "sm" | "md" | "lg";

export interface ColorPickerProps {
  /** Hex: "#RRGGBB", or "#RRGGBBAA" when translucent. */
  value?: string;
  defaultValue?: string;
  /** Every change while dragging or typing. */
  onValueChange?: (hex: string) => void;
  /** When a change is finished: pointer up, Enter, a preset or the eyedropper. Good for saving. */
  onValueCommit?: (hex: string) => void;
  /** Offer an opacity slider. Default true. */
  alpha?: boolean;
  /** Colours offered as one-click chips. Leave it out (or pass []) for no presets row at all. */
  presets?: string[];
  /** Just the picker, always visible, without the field and popover. */
  inline?: boolean;
  /** Field height: 32, 40 or 48px. Default "md". */
  size?: ColorPickerSize;
  disabled?: boolean;
  invalid?: boolean;
  /** Submits the hex with a form. */
  name?: string;
  id?: string;
  "aria-label"?: string;
  "aria-labelledby"?: string;
  className?: string;
}

const FIELD_SIZES = {
  sm: "h-8 rounded-lg pl-1.5 pr-1.5 text-[13px] gap-2",
  md: "h-10 rounded-xl pl-2 pr-2 text-sm gap-2.5",
  lg: "h-12 rounded-xl pl-2.5 pr-2.5 text-[15px] gap-3",
} as const;
const CHIP_SIZES = { sm: "size-5", md: "size-6", lg: "size-7" } as const;

const CHECKER = "repeating-conic-gradient(#3a3a3c 0% 25%, #232325 0% 50%) 50% / 8px 8px";
const HUES = "linear-gradient(90deg, #f00 0%, #ff0 17%, #0f0 33%, #0ff 50%, #00f 67%, #f0f 83%, #f00 100%)";
const SPRING = { type: "spring", stiffness: 500, damping: 30 } as const;
const WELL_EDGE = "shadow-[inset_0_1px_2px_rgba(0,0,0,0.6),inset_0_0_0_1px_rgba(0,0,0,0.35)]";

/** Pointer drag on an element, mapped to 0–1 on each axis. */
function useDrag(onMove: (x: number, y: number) => void, onEnd: () => void) {
  const [dragging, setDragging] = useState(false);
  const move = (event: PointerEvent<HTMLElement>) => {
    const r = event.currentTarget.getBoundingClientRect();
    onMove(clamp((event.clientX - r.left) / r.width), clamp((event.clientY - r.top) / r.height));
  };
  return {
    dragging,
    handlers: {
      onPointerDown: (event: PointerEvent<HTMLElement>) => {
        if (event.button !== 0) return;
        event.preventDefault();
        event.currentTarget.focus({ preventScroll: true });
        try {
          event.currentTarget.setPointerCapture(event.pointerId);
        } catch {
          // Synthetic pointers can't always be captured; the drag still works.
        }
        setDragging(true);
        move(event);
      },
      onPointerMove: (event: PointerEvent<HTMLElement>) => {
        if (dragging) move(event);
      },
      onPointerUp: () => {
        if (!dragging) return;
        setDragging(false);
        onEnd();
      },
      onPointerCancel: () => setDragging(false),
    },
  };
}

/** A ring filled with the colour it controls; it lifts while held. */
function Thumb({ colour, size, lifted, className, style }: { colour: string; size: number; lifted: boolean; className?: string; style?: CSSProperties }) {
  const reduceMotion = useReducedMotion() ?? false;
  return (
    <motion.span
      aria-hidden="true"
      animate={{ scale: lifted && !reduceMotion ? 1.18 : 1 }}
      transition={reduceMotion ? { duration: 0 } : SPRING}
      className={cn(
        "pointer-events-none absolute rounded-full border-2 border-white",
        "shadow-[0_0_0_1px_rgba(0,0,0,0.35),0_2px_6px_rgba(0,0,0,0.55),inset_0_0_0_1px_rgba(0,0,0,0.15)]",
        className
      )}
      style={{ width: size, height: size, marginLeft: -size / 2, marginTop: -size / 2, background: colour, ...style }}
    />
  );
}

const keyStep = (event: KeyboardEvent) => (event.shiftKey ? 10 : 1);

export const ColorPicker = forwardRef<HTMLButtonElement, ColorPickerProps>(function ColorPicker(
  {
    value,
    defaultValue = "#FFFFFF",
    onValueChange,
    onValueCommit,
    alpha = true,
    presets,
    inline = false,
    size = "md",
    disabled = false,
    invalid = false,
    name,
    id,
    "aria-label": ariaLabel,
    "aria-labelledby": ariaLabelledBy,
    className,
  },
  ref
) {
  const [hsva, setHsva] = useState<Hsva>(() => hexToHsva(value ?? defaultValue) ?? { h: 0, s: 0, v: 100, a: 1 });
  const hsvaRef = useRef(hsva);
  hsvaRef.current = hsva;
  const toHex = useCallback((c: Hsva) => hsvaToHex(alpha ? c : { ...c, a: 1 }), [alpha]);
  const hex = toHex(hsva);
  const lastEmitted = useRef(hex);

  // An outside value change moves the picker, unless it's the value we just sent out (keeping
  // the hue when that value is a grey).
  useEffect(() => {
    if (value === undefined) return;
    const next = hexToHsva(value);
    if (!next || toHex(next) === toHex(hsvaRef.current)) return;
    setHsva(next);
  }, [value, toHex]);

  const update = useCallback(
    (next: Hsva) => {
      const c = { ...next, a: alpha ? clamp(next.a) : 1 };
      setHsva(c);
      const out = toHex(c);
      if (out !== lastEmitted.current) {
        lastEmitted.current = out;
        onValueChange?.(out);
      }
    },
    [alpha, toHex, onValueChange]
  );
  const commit = useCallback(() => onValueCommit?.(toHex(hsvaRef.current)), [onValueCommit, toHex]);

  const panel = (
    <PickerPanel hsva={hsva} hex={hex} alpha={alpha} presets={presets} update={update} commit={commit} />
  );

  if (inline) {
    return (
      <div
        role="group"
        aria-label={ariaLabel ?? "Colour picker"}
        aria-labelledby={ariaLabelledBy}
        className={cn(
          "w-[248px] rounded-2xl border border-white/[0.08] bg-[linear-gradient(180deg,#1b1b1d_0%,#151516_100%)] p-3",
          "shadow-[inset_0_1px_0_0_rgba(255,255,255,0.05),inset_0_-1px_0_0_rgba(0,0,0,0.45),0_14px_30px_-10px_rgba(0,0,0,0.5)]",
          disabled && "pointer-events-none opacity-40",
          className
        )}
      >
        {panel}
        {name && <input type="hidden" name={name} value={hex} />}
      </div>
    );
  }

  const opaqueHex = hsvaToHex({ ...hsva, a: 1 });
  return (
    <>
      <Popover
        aria-label="Colour picker"
        className="w-[248px]"
        trigger={
          <button
            ref={ref}
            id={id}
            type="button"
            disabled={disabled}
            aria-label={ariaLabelledBy ? undefined : ariaLabel ?? `Colour, ${hex}`}
            aria-labelledby={ariaLabelledBy ? `${ariaLabelledBy} ${id ?? ""}`.trim() : undefined}
            aria-invalid={invalid || undefined}
            className={cn(
              "group/colour relative flex w-full cursor-pointer items-center border bg-[#070707] text-left select-none",
              "shadow-[inset_0_1.5px_3px_rgba(0,0,0,0.85),0_1px_0_rgba(255,255,255,0.05)]",
              "transition-[border-color,background-color] duration-150",
              "outline-white/40 outline-offset-2 focus-visible:outline focus-visible:outline-1",
              "aria-expanded:border-white/[0.18] aria-expanded:bg-[#050505]",
              invalid ? "border-[rgb(229_115_115/0.45)]" : "border-white/[0.08]",
              !disabled && !invalid && "hover:border-white/[0.13]",
              disabled && "cursor-not-allowed opacity-40",
              FIELD_SIZES[size],
              className
            )}
          >
            {/* The colour in a round socket, over a checkerboard so translucency shows. */}
            <span
              aria-hidden="true"
              className={cn("relative shrink-0 overflow-hidden rounded-full border border-white/[0.1]", CHIP_SIZES[size])}
              style={{ background: CHECKER }}
            >
              <span
                className="absolute inset-0 transition-[background-color] duration-200 motion-reduce:transition-none"
                style={{ backgroundColor: hex }}
              />
              <span className="absolute inset-0 rounded-full shadow-[inset_0_1px_2px_rgba(0,0,0,0.45)]" />
            </span>
            <span className="min-w-0 flex-1 truncate font-medium tracking-tight text-neutral-100 tabular-nums">
              {opaqueHex}
              {hsva.a < 1 && <span className="ml-1.5 font-normal text-neutral-500">{Math.round(hsva.a * 100)}%</span>}
            </span>
            <span aria-hidden="true" className="grid size-6 shrink-0 place-items-center text-neutral-500 transition-colors duration-150 group-hover/colour:text-neutral-300">
              <svg viewBox="0 0 16 16" width="14" height="14" fill="none">
                <path d="m5 6 3-3 3 3M5 10l3 3 3-3" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round" />
              </svg>
            </span>
          </button>
        }
      >
        {panel}
      </Popover>
      {name && <input type="hidden" name={name} value={hex} />}
    </>
  );
});

// ─── The picker itself ──────────────────────────────────────────────────────

function PickerPanel({
  hsva,
  hex,
  alpha,
  presets,
  update,
  commit,
}: {
  hsva: Hsva;
  hex: string;
  alpha: boolean;
  presets?: string[];
  update: (next: Hsva) => void;
  commit: () => void;
}) {
  const { h, s, v, a } = hsva;
  const opaque = hsvaToHex({ ...hsva, a: 1 });
  const pureHue = hsvaToHex({ h, s: 100, v: 100, a: 1 });
  const ringId = useId();

  const area = useDrag((x, y) => update({ ...hsva, s: x * 100, v: (1 - y) * 100 }), commit);
  const hue = useDrag((x) => update({ ...hsva, h: x * 360 }), commit);
  const opacity = useDrag((x) => update({ ...hsva, a: Math.round(x * 100) / 100 }), commit);

  // EyeDropper exists in Chromium browsers only; look for it after mount (SSR-safe).
  const [canPick, setCanPick] = useState(false);
  useEffect(() => setCanPick(typeof window !== "undefined" && "EyeDropper" in window), []);
  const pickFromScreen = async () => {
    try {
      const Dropper = (window as unknown as { EyeDropper: new () => { open: () => Promise<{ sRGBHex: string }> } }).EyeDropper;
      const { sRGBHex } = await new Dropper().open();
      const next = hexToHsva(sRGBHex);
      if (next) {
        update({ ...next, a: hsva.a });
        commit();
      }
    } catch {
      // Cancelled with Escape: nothing to do.
    }
  };

  // The hex field edits a draft; it applies on Enter or blur, and reverts if it isn't a colour.
  const [draft, setDraft] = useState(opaque.slice(1));
  const editing = useRef(false);
  useEffect(() => {
    if (!editing.current) setDraft(opaque.slice(1));
  }, [opaque]);
  const applyDraft = () => {
    editing.current = false;
    const next = hexToHsva(draft);
    if (next) {
      update({ ...next, a: draft.replace(/^#/, "").length === 8 ? next.a : hsva.a });
      commit();
    } else setDraft(opaque.slice(1));
  };

  const [alphaDraft, setAlphaDraft] = useState(String(Math.round(a * 100)));
  const editingAlpha = useRef(false);
  useEffect(() => {
    if (!editingAlpha.current) setAlphaDraft(String(Math.round(a * 100)));
  }, [a]);
  const applyAlpha = () => {
    editingAlpha.current = false;
    const n = Number(alphaDraft.replace("%", ""));
    if (Number.isFinite(n)) {
      update({ ...hsva, a: clamp(n / 100) });
      commit();
    } else setAlphaDraft(String(Math.round(a * 100)));
  };

  const onAreaKey = (event: KeyboardEvent<HTMLDivElement>) => {
    const step = keyStep(event);
    const moves: Record<string, Partial<Hsva>> = {
      ArrowLeft: { s: Math.max(s - step, 0) },
      ArrowRight: { s: Math.min(s + step, 100) },
      ArrowDown: { v: Math.max(v - step, 0) },
      ArrowUp: { v: Math.min(v + step, 100) },
      Home: { s: 0 },
      End: { s: 100 },
    };
    if (!(event.key in moves)) return;
    event.preventDefault();
    update({ ...hsva, ...moves[event.key] });
    commit();
  };
  const sliderKey = (current: number, max: number, set: (n: number) => void) => (event: KeyboardEvent<HTMLDivElement>) => {
    const step = keyStep(event) * (max === 1 ? 0.01 : 1);
    const map: Record<string, number> = {
      ArrowLeft: current - step,
      ArrowDown: current - step,
      ArrowRight: current + step,
      ArrowUp: current + step,
      Home: 0,
      End: max,
    };
    if (!(event.key in map)) return;
    event.preventDefault();
    set(Math.min(Math.max(Math.round(map[event.key] * 100) / 100, 0), max));
    commit();
  };

  const presetHsva = presets?.map((p) => ({ hex: p, c: hexToHsva(p) })).filter((p): p is { hex: string; c: Hsva } => p.c !== null);
  const currentHex = hsvaToHex(hsva, alpha && a < 1);

  return (
    <div className="flex flex-col gap-3">
      {/* Shade area: cut into the panel. */}
      <div
        role="slider"
        tabIndex={0}
        aria-roledescription="2D slider"
        aria-label="Saturation and brightness"
        aria-valuemin={0}
        aria-valuemax={100}
        aria-valuenow={Math.round(s)}
        aria-valuetext={`Saturation ${Math.round(s)}%, brightness ${Math.round(v)}%`}
        onKeyDown={onAreaKey}
        {...area.handlers}
        className={cn(
          "relative h-36 cursor-crosshair touch-none rounded-xl outline-none select-none",
          "focus-visible:ring-1 focus-visible:ring-white/40 focus-visible:ring-offset-2 focus-visible:ring-offset-[#18181a]"
        )}
        style={{
          backgroundColor: pureHue,
          backgroundImage: "linear-gradient(to top, #000, transparent), linear-gradient(to right, #fff, transparent)",
        }}
      >
        <span aria-hidden="true" className={cn("pointer-events-none absolute inset-0 rounded-xl", WELL_EDGE)} />
        <Thumb colour={opaque} size={14} lifted={area.dragging} style={{ left: `${s}%`, top: `${100 - v}%` }} />
      </div>

      {/* Hue track. */}
      <Track
        label="Hue"
        valueNow={Math.round(h)}
        max={360}
        valueText={`${Math.round(h)} degrees`}
        onKeyDown={sliderKey(h, 360, (n) => update({ ...hsva, h: n }))}
        drag={hue}
        background={HUES}
      >
        <Thumb colour={pureHue} size={16} lifted={hue.dragging} style={{ left: `${(h / 360) * 100}%` }} />
      </Track>

      {/* Opacity track: a checkerboard under the colour fading in. */}
      {alpha && (
        <Track
          label="Opacity"
          valueNow={Math.round(a * 100)}
          max={100}
          valueText={`${Math.round(a * 100)}%`}
          onKeyDown={sliderKey(a, 1, (n) => update({ ...hsva, a: n }))}
          drag={opacity}
          background={`linear-gradient(90deg, transparent, ${opaque}), ${CHECKER}`}
        >
          <Thumb colour={hex} size={16} lifted={opacity.dragging} style={{ left: `${a * 100}%` }} />
        </Track>
      )}

      {/* Values. */}
      <div className="flex items-center gap-2">
        <TextField
          size="sm"
          aria-label="Hex colour"
          leading={<span className="text-neutral-500">#</span>}
          value={draft}
          spellCheck={false}
          autoComplete="off"
          maxLength={8}
          showCount={false}
          onChange={(event) => {
            editing.current = true;
            setDraft(event.target.value.replace(/[^0-9a-f]/gi, "").toUpperCase());
          }}
          onKeyDown={(event) => {
            if (event.key === "Enter") {
              event.preventDefault();
              applyDraft();
            }
          }}
          onBlur={applyDraft}
          className="min-w-0 flex-1"
          fieldClassName="font-medium tabular-nums"
        />
        {alpha && (
          <TextField
            size="sm"
            aria-label="Opacity percent"
            inputMode="numeric"
            value={alphaDraft}
            trailing="%"
            onChange={(event) => {
              editingAlpha.current = true;
              setAlphaDraft(event.target.value.replace(/[^0-9]/g, "").slice(0, 3));
            }}
            onKeyDown={(event) => {
              if (event.key === "Enter") {
                event.preventDefault();
                applyAlpha();
              }
            }}
            onBlur={applyAlpha}
            className="w-[72px] shrink-0"
            fieldClassName="tabular-nums"
          />
        )}
        {canPick && (
          <button
            type="button"
            aria-label="Pick a colour from the screen"
            onClick={pickFromScreen}
            className={cn(
              "grid size-8 shrink-0 cursor-pointer place-items-center rounded-lg text-neutral-400",
              "transition-colors duration-150 hover:bg-[#0c0c0d] hover:text-neutral-100",
              "outline-white/40 outline-offset-2 focus-visible:outline focus-visible:outline-1"
            )}
          >
            <svg viewBox="0 0 16 16" width="15" height="15" fill="none" aria-hidden="true">
              <path d="m9.5 3.5 3 3M11 2a1.4 1.4 0 0 1 2 0l1 1a1.4 1.4 0 0 1 0 2l-1.5 1.5-3-3L11 2Z" stroke="currentColor" strokeWidth="1.3" strokeLinejoin="round" />
              <path d="m9.5 5-6 6-.75 2.25L5 12.5l6-6" stroke="currentColor" strokeWidth="1.3" strokeLinecap="round" strokeLinejoin="round" />
            </svg>
          </button>
        )}
      </div>

      {/* Presets: chips in sockets; a ring glides to the one in use. */}
      {presetHsva && presetHsva.length > 0 && (
        <div className="flex flex-wrap gap-1.5 border-t border-black/50 pt-3 shadow-[inset_0_1px_0_rgba(255,255,255,0.04)]">
          <LayoutGroup id={ringId}>
            {presetHsva.map(({ hex: preset, c }) => {
              const chosen = hsvaToHex(c, alpha && c.a < 1) === currentHex;
              return (
                <button
                  key={preset}
                  type="button"
                  aria-label={preset.toUpperCase()}
                  aria-pressed={chosen}
                  onClick={() => {
                    update(c);
                    commit();
                  }}
                  className="relative grid size-[22px] cursor-pointer place-items-center rounded-full outline-white/40 outline-offset-2 focus-visible:outline focus-visible:outline-1"
                >
                  {chosen && (
                    <motion.span
                      aria-hidden="true"
                      layoutId="colour-preset-ring"
                      transition={SPRING}
                      className="absolute -inset-[3px] rounded-full border border-white/70"
                    />
                  )}
                  <span aria-hidden="true" className="relative size-full overflow-hidden rounded-full border border-white/[0.1]" style={{ background: CHECKER }}>
                    <span className="absolute inset-0" style={{ backgroundColor: hsvaToHex(c) }} />
                    <span className="absolute inset-0 rounded-full shadow-[inset_0_1px_2px_rgba(0,0,0,0.45)]" />
                  </span>
                </button>
              );
            })}
          </LayoutGroup>
        </div>
      )}
    </div>
  );
}

function Track({
  label,
  valueNow,
  max,
  valueText,
  onKeyDown,
  drag,
  background,
  children,
}: {
  label: string;
  valueNow: number;
  max: number;
  valueText: string;
  onKeyDown: (event: KeyboardEvent<HTMLDivElement>) => void;
  drag: ReturnType<typeof useDrag>;
  background: string;
  children: ReactNode;
}) {
  return (
    <div
      role="slider"
      tabIndex={0}
      aria-label={label}
      aria-valuemin={0}
      aria-valuemax={max}
      aria-valuenow={valueNow}
      aria-valuetext={valueText}
      aria-orientation="horizontal"
      onKeyDown={onKeyDown}
      {...drag.handlers}
      // A taller hit area than the 10px track it draws, so it's easy to grab.
      className={cn(
        "relative flex h-5 cursor-pointer touch-none items-center rounded-full outline-none select-none",
        "focus-visible:ring-1 focus-visible:ring-white/40 focus-visible:ring-offset-2 focus-visible:ring-offset-[#18181a]"
      )}
    >
      <span aria-hidden="true" className="absolute inset-x-0 h-2.5 rounded-full" style={{ background }}>
        <span className={cn("absolute inset-0 rounded-full", WELL_EDGE)} />
      </span>
      {/* Thumbs are centred on the track's line. */}
      <span className="pointer-events-none absolute inset-x-0 top-1/2 h-0">{children}</span>
    </div>
  );
}

"use client";

import {
  Children,
  cloneElement,
  createContext,
  isValidElement,
  useCallback,
  useContext,
  useEffect,
  useId,
  useLayoutEffect,
  useRef,
  useState,
  type FocusEvent,
  type KeyboardEvent,
  type MouseEvent,
  type ReactElement,
  type ReactNode,
  type Ref,
} from "react";
import { LayoutGroup, motion, useReducedMotion } from "framer-motion";
import { cn } from "@/lib/utils";

// Popover and Dropdown Menu share one floating panel. It opens on the browser's top layer (the
// native `popover` attribute), so no overflow or z-index can clip it; it sits 8px off its trigger,
// flips to the other side when there's no room and stays inside the viewport. It closes on Escape
// (focus goes back to the trigger), on a click outside, and when focus leaves it. Entrance: scale
// 0.97 → 1 and fade over 160ms, growing from the trigger's side.
//
// Popover holds anything: a form, a note, a picker. DropdownMenu fills the same panel with a list
// of actions: arrow keys, Home/End and type-ahead move a raised highlight that glides from item
// to item; Enter or a click runs the item and closes the menu. MenuSub opens a second panel to
// the side (hover, or ArrowRight); MenuRadioGroup holds pick-one items. Menubar (Menubar.tsx)
// lines several DropdownMenus up in a bar.

export type PopoverSide = "top" | "bottom" | "left" | "right";
export type PopoverAlign = "start" | "center" | "end";

const GAP = 8;
const EDGE = 8;
const SPRING = { type: "spring", stiffness: 500, damping: 40 } as const;

const PANEL = cn(
  "fixed inset-auto m-0 overflow-y-auto overscroll-contain text-neutral-100 [scrollbar-color:#2a2a2c_transparent] [scrollbar-width:thin]",
  "border border-white/[0.08] bg-[linear-gradient(180deg,#1b1b1d_0%,#151516_100%)]",
  "shadow-[inset_0_1px_0_0_rgba(255,255,255,0.05),inset_0_-1.5px_0_0_rgba(0,0,0,0.45),0_24px_60px_-16px_rgba(0,0,0,0.9),0_6px_18px_-6px_rgba(0,0,0,0.7)]",
  "transition-[opacity,scale] duration-[160ms] ease-[cubic-bezier(0.32,0.72,0,1)] motion-reduce:transition-opacity",
  "starting:scale-[0.97] starting:opacity-0",
  "data-[side=bottom]:origin-top data-[side=top]:origin-bottom data-[side=left]:origin-right data-[side=right]:origin-left",
  "outline-none"
);

// Bottom layer under every item's content, so it never paints over text while gliding down.
const HIGHLIGHT = cn(
  "absolute inset-0 z-0 rounded-lg border border-white/[0.07] border-t-white/[0.13]",
  "bg-[linear-gradient(180deg,#232325_0%,#1c1c1e_100%)]",
  "shadow-[inset_0_1px_0_rgba(255,255,255,0.06),inset_0_-1px_0_rgba(0,0,0,0.5),0_4px_10px_-4px_rgba(0,0,0,0.8),0_1px_2px_rgba(0,0,0,0.5)]"
);

const FOCUSABLE = 'a[href],button:not([disabled]),input:not([disabled]),select:not([disabled]),textarea:not([disabled]),[tabindex]:not([tabindex="-1"])';
const ITEMS = '[role^="menuitem"]:not([aria-disabled="true"])';

// ─── Shared floating panel ──────────────────────────────────────────────────

function useOpenState(open: boolean | undefined, defaultOpen: boolean, onOpenChange?: (open: boolean) => void) {
  const [own, setOwn] = useState(defaultOpen);
  const isOpen = open ?? own;
  const setOpen = useCallback(
    (next: boolean) => {
      if (open === undefined) setOwn(next);
      onOpenChange?.(next);
    },
    [open, onOpenChange]
  );
  return [isOpen, setOpen] as const;
}

/** The element's own ref, on React 19 (props.ref) and 18 (element.ref). */
function elementRef(element: ReactElement): Ref<HTMLElement> | undefined {
  return (element.props as { ref?: Ref<HTMLElement> }).ref ?? (element as unknown as { ref?: Ref<HTMLElement> }).ref;
}

function assignRef<T>(ref: Ref<T> | undefined, value: T) {
  if (typeof ref === "function") ref(value);
  else if (ref) (ref as { current: T }).current = value;
}

/**
 * Where the panel goes: the preferred side if it fits, else the opposite one if that fits, else
 * whichever has more room, with the panel capped to that room and scrolling inside. Kept on screen.
 */
function place(trigger: HTMLElement, panel: HTMLElement, side: PopoverSide, align: PopoverAlign, offset: number) {
  // Re-measuring drops the height cap for a moment; keep the panel's own scroll where it was.
  const scrolled = panel.scrollTop;
  panel.style.maxHeight = "";
  const t = trigger.getBoundingClientRect();
  const width = panel.offsetWidth;
  const vw = window.innerWidth;
  const vh = window.innerHeight;
  let height = panel.offsetHeight;

  const room = {
    bottom: vh - EDGE - t.bottom - offset,
    top: t.top - offset - EDGE,
    right: vw - EDGE - t.right - offset,
    left: t.left - offset - EDGE,
  };
  const opposite = { top: "bottom", bottom: "top", left: "right", right: "left" } as const;
  const vertical0 = side === "top" || side === "bottom";
  const need = vertical0 ? height : width;
  let actual: PopoverSide = side;
  if (room[side] < need) {
    actual = room[opposite[side]] >= need || room[opposite[side]] > room[side] ? opposite[side] : side;
  }
  // Still too tall for its side: cap it and let it scroll.
  if ((actual === "top" || actual === "bottom") && height > room[actual]) {
    height = Math.max(room[actual], 120);
    panel.style.maxHeight = `${height}px`;
  }

  const vertical = actual === "top" || actual === "bottom";
  const crossStart = vertical ? t.left : t.top;
  const crossSize = vertical ? t.width : t.height;
  const ownSize = vertical ? width : height;
  let cross = align === "start" ? crossStart : align === "end" ? crossStart + crossSize - ownSize : crossStart + crossSize / 2 - ownSize / 2;
  cross = Math.min(Math.max(cross, EDGE), (vertical ? vw : vh) - ownSize - EDGE);

  const main =
    actual === "bottom" ? t.bottom + offset : actual === "top" ? t.top - offset - height : actual === "right" ? t.right + offset : t.left - offset - width;

  panel.style.left = `${vertical ? cross : main}px`;
  panel.style.top = `${vertical ? main : cross}px`;
  panel.dataset.side = actual;
  panel.scrollTop = scrolled;
}

interface FloatingProps {
  trigger: ReactElement;
  open: boolean;
  setOpen: (open: boolean) => void;
  side: PopoverSide;
  align: PopoverAlign;
  offset: number;
  matchTriggerWidth: boolean;
  role: "dialog" | "menu";
  /** Where focus goes on open. */
  initialFocus: (panel: HTMLElement) => void;
  onTriggerKeyDown?: (event: KeyboardEvent<HTMLElement>) => void;
  onPanelKeyDown?: (event: KeyboardEvent<HTMLDivElement>) => void;
  className?: string;
  ariaLabel?: string;
  children: ReactNode;
}

function Floating({
  trigger,
  open,
  setOpen,
  side,
  align,
  offset,
  matchTriggerWidth,
  role,
  initialFocus,
  onTriggerKeyDown,
  onPanelKeyDown,
  className,
  ariaLabel,
  children,
}: FloatingProps) {
  const panelId = useId();
  const triggerRef = useRef<HTMLElement | null>(null);
  const panelRef = useRef<HTMLDivElement>(null);
  const focusRef = useRef(initialFocus);
  focusRef.current = initialFocus;

  const close = useCallback(
    (returnFocus: boolean) => {
      setOpen(false);
      if (returnFocus) triggerRef.current?.focus();
    },
    [setOpen]
  );

  // Show on the top layer, place, move focus in; keep placed on scroll and resize.
  useLayoutEffect(() => {
    const panel = panelRef.current;
    const anchor = triggerRef.current;
    if (!panel || !anchor) return;
    if (!open) {
      if (panel.matches(":popover-open")) panel.hidePopover();
      return;
    }
    if (!panel.matches(":popover-open")) panel.showPopover();
    if (matchTriggerWidth) panel.style.minWidth = `${anchor.getBoundingClientRect().width}px`;
    const update = () => place(anchor, panel, side, align, offset);
    // Follow the trigger when the page (or a scroller around it) scrolls, but not when the
    // panel scrolls its own content: re-placing it then would fight the user's scroll.
    const onScroll = (event: Event) => {
      if (event.target instanceof Node && panel.contains(event.target)) return;
      update();
    };
    update();
    focusRef.current(panel);
    window.addEventListener("resize", update);
    window.addEventListener("scroll", onScroll, true);
    return () => {
      window.removeEventListener("resize", update);
      window.removeEventListener("scroll", onScroll, true);
    };
  }, [open, side, align, offset, matchTriggerWidth]);

  // A click outside both the trigger and the panel closes it, without stealing focus.
  useEffect(() => {
    if (!open) return;
    const onPointerDown = (event: PointerEvent) => {
      const target = event.target as Node;
      if (triggerRef.current?.contains(target) || panelRef.current?.contains(target)) return;
      close(false);
    };
    document.addEventListener("pointerdown", onPointerDown);
    return () => document.removeEventListener("pointerdown", onPointerDown);
  }, [open, close]);

  const anchor = isValidElement(trigger)
    ? cloneElement(trigger as ReactElement<Record<string, unknown>>, {
        ref: (node: HTMLElement | null) => {
          triggerRef.current = node;
          assignRef(elementRef(trigger), node);
        },
        "aria-haspopup": role,
        "aria-expanded": open,
        "aria-controls": open ? panelId : undefined,
        onClick: (event: MouseEvent<HTMLElement>) => {
          (trigger.props as { onClick?: (event: MouseEvent<HTMLElement>) => void }).onClick?.(event);
          if (!event.defaultPrevented) setOpen(!open);
        },
        onKeyDown: (event: KeyboardEvent<HTMLElement>) => {
          (trigger.props as { onKeyDown?: (event: KeyboardEvent<HTMLElement>) => void }).onKeyDown?.(event);
          if (!event.defaultPrevented) onTriggerKeyDown?.(event);
        },
      })
    : null;

  return (
    <>
      {anchor}
      <div
        ref={panelRef}
        id={panelId}
        popover="manual"
        role={role}
        aria-label={ariaLabel}
        tabIndex={-1}
        data-state={open ? "open" : "closed"}
        onKeyDown={(event) => {
          // A submenu's panel sits inside this one in the DOM; its keys are its own business.
          if ((event.target as HTMLElement).closest("[popover]") !== event.currentTarget) return;
          if (event.key === "Escape") {
            event.preventDefault();
            event.stopPropagation();
            close(true);
            return;
          }
          onPanelKeyDown?.(event);
        }}
        onBlur={(event) => {
          // Focus left for somewhere other than the trigger: close quietly.
          const next = event.relatedTarget as Node | null;
          if (next && !panelRef.current?.contains(next) && !triggerRef.current?.contains(next)) close(false);
        }}
        className={cn(PANEL, className)}
      >
        {open && (
          <FloatingContext.Provider value={{ close: () => close(true) }}>{children}</FloatingContext.Provider>
        )}
      </div>
    </>
  );
}

const FloatingContext = createContext<{ close: () => void } | null>(null);

/** Closes the surrounding Popover or DropdownMenu and returns focus to its trigger. */
export function usePopoverClose() {
  return useContext(FloatingContext)?.close ?? (() => {});
}

// ─── Popover ────────────────────────────────────────────────────────────────

export interface PopoverProps {
  /** The element that opens it, usually a Button. It gets the click and aria wiring. */
  trigger: ReactElement;
  children: ReactNode;
  open?: boolean;
  defaultOpen?: boolean;
  onOpenChange?: (open: boolean) => void;
  /** Preferred side; flips when there's no room. Default "bottom". */
  side?: PopoverSide;
  /** Default "start". */
  align?: PopoverAlign;
  /** Gap to the trigger in px. Default 8. */
  offset?: number;
  /** At least as wide as the trigger. */
  matchTriggerWidth?: boolean;
  /** Names the panel for screen readers. */
  "aria-label"?: string;
  /** Classes for the panel. */
  className?: string;
}

export function Popover({
  trigger,
  children,
  open: openProp,
  defaultOpen = false,
  onOpenChange,
  side = "bottom",
  align = "start",
  offset = GAP,
  matchTriggerWidth = false,
  "aria-label": ariaLabel,
  className,
}: PopoverProps) {
  const [open, setOpen] = useOpenState(openProp, defaultOpen, onOpenChange);
  return (
    <Floating
      trigger={trigger}
      open={open}
      setOpen={setOpen}
      side={side}
      align={align}
      offset={offset}
      matchTriggerWidth={matchTriggerWidth}
      role="dialog"
      ariaLabel={ariaLabel}
      initialFocus={(panel) => (panel.querySelector<HTMLElement>(FOCUSABLE) ?? panel).focus({ preventScroll: true })}
      className={cn("w-max max-w-[min(360px,calc(100vw-16px))] rounded-2xl p-3", className)}
    >
      {children}
    </Floating>
  );
}

// ─── Dropdown Menu ──────────────────────────────────────────────────────────

const MenuContext = createContext<{
  highlighted: string | null;
  setHighlighted: (id: string | null) => void;
  close: () => void;
  layoutId: string;
  reduceMotion: boolean;
} | null>(null);

/** Items that belong to `panel` itself, not to a submenu nested inside it. */
const ownItems = (panel: HTMLElement | null) =>
  Array.from(panel?.querySelectorAll<HTMLElement>(ITEMS) ?? []).filter((item) => item.closest('[role="menu"]') === panel);

/** Arrow keys, Home/End and type-ahead within one menu panel. Returns true if it used the key. */
function navigateItems(event: KeyboardEvent<HTMLElement>, panel: HTMLElement, ahead: { text: string; timer: number }) {
  const list = ownItems(panel);
  if (!list.length) return false;
  const current = list.indexOf(document.activeElement as HTMLElement);
  const focusAt = (index: number) => list[(index + list.length) % list.length].focus({ preventScroll: false });
  switch (event.key) {
    case "ArrowDown":
      event.preventDefault();
      focusAt(current + 1);
      return true;
    case "ArrowUp":
      event.preventDefault();
      focusAt(current < 0 ? -1 : current - 1);
      return true;
    case "Home":
      event.preventDefault();
      focusAt(0);
      return true;
    case "End":
      event.preventDefault();
      focusAt(-1);
      return true;
  }
  // Type-ahead: letters typed within half a second jump to the first match.
  if (event.key.length === 1 && !event.metaKey && !event.ctrlKey && !event.altKey) {
    window.clearTimeout(ahead.timer);
    ahead.text += event.key.toLowerCase();
    ahead.timer = window.setTimeout(() => (ahead.text = ""), 500);
    const ordered = [...list.slice(current + 1), ...list.slice(0, current + 1)];
    const match = ordered.find((item) => (item.dataset.label ?? item.textContent ?? "").trim().toLowerCase().startsWith(ahead.text));
    match?.focus();
    return Boolean(match);
  }
  return false;
}

export interface DropdownMenuProps {
  trigger: ReactElement;
  /** MenuItem, MenuCheckboxItem, MenuRadioGroup, MenuSub, MenuGroup, MenuLabel and MenuSeparator. */
  children: ReactNode;
  open?: boolean;
  defaultOpen?: boolean;
  onOpenChange?: (open: boolean) => void;
  /** Default "bottom". */
  side?: PopoverSide;
  /** Default "start". */
  align?: PopoverAlign;
  offset?: number;
  /** Default true: at least as wide as the trigger. */
  matchTriggerWidth?: boolean;
  "aria-label"?: string;
  className?: string;
  /** ArrowLeft/ArrowRight inside the menu (when no submenu takes it). Menubar uses this to move between menus. */
  onEdgeNavigate?: (direction: -1 | 1) => void;
  /** Land on the first item whenever it opens, however it was opened. */
  autoFocusFirst?: boolean;
}

export function DropdownMenu({
  trigger,
  children,
  open: openProp,
  defaultOpen = false,
  onOpenChange,
  side = "bottom",
  align = "start",
  offset = GAP,
  matchTriggerWidth = true,
  "aria-label": ariaLabel,
  className,
  onEdgeNavigate,
  autoFocusFirst = false,
}: DropdownMenuProps) {
  const [open, setOpen] = useOpenState(openProp, defaultOpen, onOpenChange);
  const [highlighted, setHighlighted] = useState<string | null>(null);
  const reduceMotion = useReducedMotion() ?? false;
  const layoutId = useId();
  // Keyboard opening lands on the first (or last) item; a click opens with nothing highlighted.
  const startAt = useRef<"panel" | "first" | "last">("panel");
  const typeahead = useRef({ text: "", timer: 0 });

  return (
    <MenuContext.Provider
      value={{ highlighted, setHighlighted, close: () => setOpen(false), layoutId, reduceMotion }}
    >
      <Floating
        trigger={trigger}
        open={open}
        setOpen={(next) => {
          if (!next) setHighlighted(null);
          setOpen(next);
        }}
        side={side}
        align={align}
        offset={offset}
        matchTriggerWidth={matchTriggerWidth}
        role="menu"
        ariaLabel={ariaLabel}
        initialFocus={(panel) => {
          const list = ownItems(panel);
          const mode = autoFocusFirst ? "first" : startAt.current;
          const target = mode === "first" ? list[0] : mode === "last" ? list[list.length - 1] : panel;
          (target ?? panel).focus({ preventScroll: true });
          startAt.current = "panel";
        }}
        onTriggerKeyDown={(event) => {
          if (event.key === "ArrowDown" || event.key === "ArrowUp") {
            event.preventDefault();
            startAt.current = event.key === "ArrowUp" ? "last" : "first";
            setOpen(true);
          } else if (event.key === "Enter" || event.key === " ") {
            // The click that follows opens it; this just says where focus should land.
            startAt.current = "first";
          }
        }}
        onPanelKeyDown={(event) => {
          if (event.key === "Tab") {
            setOpen(false);
            return;
          }
          if (event.key === "ArrowLeft" || event.key === "ArrowRight") {
            if (onEdgeNavigate) {
              event.preventDefault();
              onEdgeNavigate(event.key === "ArrowLeft" ? -1 : 1);
            }
            return;
          }
          navigateItems(event, event.currentTarget, typeahead.current);
        }}
        className={cn("min-w-[200px] max-w-[min(320px,calc(100vw-16px))] rounded-xl p-1", className)}
      >
        <LayoutGroup id={layoutId}>{children}</LayoutGroup>
      </Floating>
    </MenuContext.Provider>
  );
}

interface MenuItemBaseProps {
  children: ReactNode;
  icon?: ReactNode;
  /** Right-aligned hint, e.g. "⌘K". */
  shortcut?: ReactNode;
  disabled?: boolean;
  /** Danger tint for actions like Delete. */
  destructive?: boolean;
  /** Plain text for type-ahead when the children aren't plain text. */
  textValue?: string;
  className?: string;
}

function useMenuItem(disabled: boolean) {
  const menu = useContext(MenuContext);
  const id = useId();
  return {
    menu,
    id,
    active: menu?.highlighted === id,
    handlers: {
      onFocus: () => menu?.setHighlighted(id),
      // Moving between items hands the highlight over (so it glides); leaving the menu clears it.
      onBlur: (event: FocusEvent<HTMLElement>) => {
        const next = event.relatedTarget as HTMLElement | null;
        if (next?.closest('[role="menu"]') === event.currentTarget.closest('[role="menu"]') && next?.matches(ITEMS)) return;
        if (menu?.highlighted === id) menu.setHighlighted(null);
      },
      onPointerMove: (event: MouseEvent<HTMLElement>) => {
        if (!disabled && document.activeElement !== event.currentTarget) event.currentTarget.focus({ preventScroll: true });
      },
    },
  };
}

function ItemBody({
  active,
  icon,
  shortcut,
  destructive,
  check,
  children,
}: {
  active: boolean;
  icon?: ReactNode;
  shortcut?: ReactNode;
  destructive?: boolean;
  check?: ReactNode;
  children: ReactNode;
}) {
  const menu = useContext(MenuContext);
  return (
    <>
      {/* The highlight: one raised segment that glides from item to item. */}
      {active && (
        <motion.span
          aria-hidden="true"
          data-highlight=""
          layoutId={`${menu?.layoutId}-highlight`}
          transition={menu?.reduceMotion ? { duration: 0 } : SPRING}
          className={HIGHLIGHT}
        />
      )}
      {check}
      {icon && (
        <span
          aria-hidden="true"
          className={cn(
            "relative inline-flex shrink-0 [&_svg]:size-4 transition-colors duration-150",
            destructive ? "text-[rgb(229_115_115)]" : active ? "text-neutral-100" : "text-neutral-500"
          )}
        >
          {icon}
        </span>
      )}
      <span
        className={cn(
          "relative min-w-0 flex-1 truncate transition-colors duration-150",
          destructive ? (active ? "text-[rgb(240_140_140)]" : "text-[rgb(229_115_115)]") : active ? "text-neutral-50" : "text-neutral-300"
        )}
      >
        {children}
      </span>
      {shortcut && (
        <span className={cn("relative shrink-0 text-xs tabular-nums transition-colors duration-150", active ? "text-neutral-400" : "text-neutral-600")}>
          {shortcut}
        </span>
      )}
    </>
  );
}

const ITEM = cn(
  "relative flex h-9 w-full cursor-pointer items-center gap-2.5 rounded-lg px-2.5 text-left text-sm tracking-tight select-none outline-none [&>:not([data-highlight])]:z-[1]",
  "aria-disabled:cursor-not-allowed aria-disabled:opacity-40"
);

export interface MenuItemProps extends MenuItemBaseProps {
  /** Runs on click or Enter. Call event.preventDefault() to keep the menu open. */
  onSelect?: (event: MouseEvent<HTMLElement>) => void;
  /** Render as a link. */
  href?: string;
}

export function MenuItem({ children, icon, shortcut, disabled = false, destructive = false, textValue, onSelect, href, className }: MenuItemProps) {
  const { menu, active, handlers } = useMenuItem(disabled);
  const close = useContext(FloatingContext)?.close;
  const props = {
    role: "menuitem",
    tabIndex: -1,
    "aria-disabled": disabled || undefined,
    "data-label": textValue,
    "data-highlighted": active ? "" : undefined,
    className: cn(ITEM, className),
    ...handlers,
    onClick: (event: MouseEvent<HTMLElement>) => {
      if (disabled) {
        event.preventDefault();
        return;
      }
      onSelect?.(event);
      if (!event.defaultPrevented) {
        menu?.setHighlighted(null);
        close?.();
      }
    },
  };
  const body = (
    <ItemBody active={active} icon={icon} shortcut={shortcut} destructive={destructive}>
      {children}
    </ItemBody>
  );
  return href && !disabled ? (
    <a href={href} {...props}>
      {body}
    </a>
  ) : (
    <button type="button" {...props}>
      {body}
    </button>
  );
}

export interface MenuCheckboxItemProps extends Omit<MenuItemBaseProps, "destructive"> {
  checked: boolean;
  onCheckedChange?: (checked: boolean) => void;
}

/** A toggle. Stays open on select, so several can be flipped in a row. */
export function MenuCheckboxItem({ children, icon, shortcut, disabled = false, textValue, checked, onCheckedChange, className }: MenuCheckboxItemProps) {
  const { active, handlers } = useMenuItem(disabled);
  return (
    <button
      type="button"
      role="menuitemcheckbox"
      aria-checked={checked}
      tabIndex={-1}
      aria-disabled={disabled || undefined}
      data-label={textValue}
      data-highlighted={active ? "" : undefined}
      className={cn(ITEM, className)}
      {...handlers}
      onClick={() => {
        if (!disabled) onCheckedChange?.(!checked);
      }}
    >
      <ItemBody
        active={active}
        icon={icon}
        shortcut={shortcut}
        check={
          // A small socket; checked, a popout check rises in it.
          <span
            aria-hidden="true"
            className={cn(
              "relative grid size-4 shrink-0 place-items-center rounded-[5px] border transition-[background,border-color,box-shadow] duration-150",
              checked
                ? "border-white/40 bg-[linear-gradient(180deg,#f5f5f5_0%,#d9d9d9_100%)] text-neutral-950 shadow-[inset_0_1px_0_rgba(255,255,255,0.9),0_1px_2px_rgba(0,0,0,0.6)]"
                : "border-white/[0.08] bg-[#070707] shadow-[inset_0_1px_2px_rgba(0,0,0,0.85)]"
            )}
          >
            {checked && (
              <svg viewBox="0 0 12 12" width="10" height="10" fill="none">
                <path d="M2.6 6.3 4.9 8.6 9.4 3.6" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" />
              </svg>
            )}
          </span>
        }
      >
        {children}
      </ItemBody>
    </button>
  );
}

/** A quiet heading over a group of items. */
export function MenuLabel({ children, className }: { children: ReactNode; className?: string }) {
  return (
    <div role="presentation" className={cn("px-2.5 pt-2 pb-1 text-xs font-medium text-neutral-500 select-none", className)}>
      {children}
    </div>
  );
}

/** A machined cut line between groups. */
export function MenuSeparator({ className }: { className?: string }) {
  return (
    <div
      role="separator"
      className={cn("mx-1 my-1.5 h-px bg-black/60 shadow-[0_1px_0_rgba(255,255,255,0.05)]", className)}
    />
  );
}

/** Groups items for screen readers; pass a label to show a MenuLabel above them. */
export function MenuGroup({ label, children }: { label?: ReactNode; children: ReactNode }) {
  const labelId = useId();
  return (
    <div role="group" aria-labelledby={label ? labelId : undefined}>
      {label && (
        <div id={labelId}>
          <MenuLabel>{label}</MenuLabel>
        </div>
      )}
      {Children.toArray(children)}
    </div>
  );
}

// ─── Submenu ────────────────────────────────────────────────────────────────

export interface MenuSubProps {
  /** The row that opens it. */
  label: ReactNode;
  icon?: ReactNode;
  disabled?: boolean;
  textValue?: string;
  /** Items of the submenu. */
  children: ReactNode;
  className?: string;
}

/**
 * A row that opens a second menu to its side: on hover (after a beat), ArrowRight, Enter or
 * Space. ArrowLeft or Escape closes just the submenu and returns to its row. Its panel lives
 * inside the parent's panel in the DOM (on the top layer visually), so the parent's outside-click
 * and focus checks count it as inside.
 */
export function MenuSub({ label, icon, disabled = false, textValue, children, className }: MenuSubProps) {
  const { menu, id, active, handlers } = useMenuItem(disabled);
  const reduceMotion = useReducedMotion() ?? false;
  const [open, setOpen] = useState(false);
  const [highlighted, setHighlighted] = useState<string | null>(null);
  const triggerRef = useRef<HTMLButtonElement>(null);
  const panelRef = useRef<HTMLDivElement>(null);
  const focusFirst = useRef(false);
  const timer = useRef(0);
  const ahead = useRef({ text: "", timer: 0 });
  const layoutId = useId();
  const panelId = useId();

  const show = (withFocus: boolean) => {
    if (disabled) return;
    window.clearTimeout(timer.current);
    focusFirst.current = withFocus;
    if (open && withFocus) ownItems(panelRef.current)[0]?.focus({ preventScroll: true });
    setOpen(true);
  };
  const hide = (returnFocus: boolean) => {
    window.clearTimeout(timer.current);
    setOpen(false);
    setHighlighted(null);
    if (returnFocus) triggerRef.current?.focus({ preventScroll: true });
  };

  // Another row of the parent highlighted: close after a beat, so a diagonal move into the
  // submenu across a neighbouring row doesn't snap it shut.
  useEffect(() => {
    if (!open || !menu?.highlighted || menu.highlighted === id) return;
    timer.current = window.setTimeout(() => hide(false), 160);
    return () => window.clearTimeout(timer.current);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [menu?.highlighted, open, id]);

  useEffect(() => () => window.clearTimeout(timer.current), []);

  useLayoutEffect(() => {
    const panel = panelRef.current;
    const trigger = triggerRef.current;
    if (!panel || !trigger) return;
    if (!open) {
      if (panel.matches(":popover-open")) panel.hidePopover();
      return;
    }
    if (!panel.matches(":popover-open")) panel.showPopover();
    place(trigger, panel, "right", "start", 4);
    // Line the first item up with the row that opened it (panel padding + border).
    panel.style.top = `${parseFloat(panel.style.top) - 5}px`;
    if (focusFirst.current) ownItems(panel)[0]?.focus({ preventScroll: true });
    focusFirst.current = false;
  }, [open]);

  return (
    <>
      <button
        ref={triggerRef}
        type="button"
        role="menuitem"
        tabIndex={-1}
        aria-haspopup="menu"
        aria-expanded={open}
        aria-controls={open ? panelId : undefined}
        aria-disabled={disabled || undefined}
        data-label={textValue}
        data-highlighted={active || open ? "" : undefined}
        data-state={open ? "open" : "closed"}
        className={cn(ITEM, className)}
        {...handlers}
        onPointerMove={(event) => {
          handlers.onPointerMove(event);
          if (disabled || open) return;
          window.clearTimeout(timer.current);
          timer.current = window.setTimeout(() => show(false), 100);
        }}
        onPointerLeave={() => {
          if (!open) window.clearTimeout(timer.current);
        }}
        onClick={() => (open ? ownItems(panelRef.current)[0]?.focus() : show(true))}
        onKeyDown={(event) => {
          if (event.key === "ArrowRight" || event.key === "Enter" || event.key === " ") {
            event.preventDefault();
            event.stopPropagation();
            show(true);
          }
        }}
      >
        <ItemBody active={active || open} icon={icon} shortcut={<ChevronRight />}>
          {label}
        </ItemBody>
      </button>

      <div
        ref={panelRef}
        id={panelId}
        popover="manual"
        role="menu"
        aria-label={typeof label === "string" ? label : undefined}
        tabIndex={-1}
        onPointerEnter={() => window.clearTimeout(timer.current)}
        onKeyDown={(event) => {
          // Only this panel's own keys; a deeper submenu handles its own.
          if ((event.target as HTMLElement).closest("[popover]") !== event.currentTarget) return;
          if (event.key === "ArrowLeft" || event.key === "Escape") {
            event.preventDefault();
            event.stopPropagation();
            hide(true);
            return;
          }
          if (event.key === "Tab") return; // let the root menu close on Tab
          if (navigateItems(event, event.currentTarget, ahead.current) || event.key === "ArrowRight") event.stopPropagation();
        }}
        className={cn(PANEL, "min-w-[200px] max-w-[min(320px,calc(100vw-16px))] rounded-xl p-1")}
      >
        {open && (
          <MenuContext.Provider
            value={{ highlighted, setHighlighted, close: menu?.close ?? (() => {}), layoutId, reduceMotion }}
          >
            <LayoutGroup id={layoutId}>{children}</LayoutGroup>
          </MenuContext.Provider>
        )}
      </div>
    </>
  );
}

function ChevronRight() {
  return (
    <svg viewBox="0 0 12 12" width="12" height="12" fill="none" aria-hidden="true">
      <path d="m4.5 2.75 3.25 3.25-3.25 3.25" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round" />
    </svg>
  );
}

// ─── Radio items ────────────────────────────────────────────────────────────

const RadioContext = createContext<{ value: string | undefined; onValueChange?: (value: string) => void } | null>(null);

export interface MenuRadioGroupProps {
  value?: string;
  onValueChange?: (value: string) => void;
  /** Shows a MenuLabel above the items. */
  label?: ReactNode;
  children: ReactNode;
}

/** A pick-one group inside a menu. */
export function MenuRadioGroup({ value, onValueChange, label, children }: MenuRadioGroupProps) {
  return (
    <RadioContext.Provider value={{ value, onValueChange }}>
      <MenuGroup label={label}>{children}</MenuGroup>
    </RadioContext.Provider>
  );
}

export interface MenuRadioItemProps extends Omit<MenuItemBaseProps, "destructive" | "icon"> {
  value: string;
}

/** One choice in a MenuRadioGroup. Stays open on select, so the change can be seen. */
export function MenuRadioItem({ value, children, shortcut, disabled = false, textValue, className }: MenuRadioItemProps) {
  const group = useContext(RadioContext);
  const { active, handlers } = useMenuItem(disabled);
  const checked = group?.value === value;
  return (
    <button
      type="button"
      role="menuitemradio"
      aria-checked={checked}
      tabIndex={-1}
      aria-disabled={disabled || undefined}
      data-label={textValue}
      data-highlighted={active ? "" : undefined}
      className={cn(ITEM, className)}
      {...handlers}
      onClick={() => {
        if (!disabled) group?.onValueChange?.(value);
      }}
    >
      <ItemBody
        active={active}
        shortcut={shortcut}
        check={
          // A round well; chosen, a popout pearl rises in its centre.
          <span
            aria-hidden="true"
            className="relative grid size-4 shrink-0 place-items-center rounded-full border border-white/[0.08] bg-[#070707] shadow-[inset_0_1px_2px_rgba(0,0,0,0.85)]"
          >
            <span
              className={cn(
                "size-[7px] rounded-full bg-[linear-gradient(180deg,#f5f5f5_0%,#d9d9d9_100%)] shadow-[inset_0_1px_0_rgba(255,255,255,0.9),0_1px_2px_rgba(0,0,0,0.6)]",
                "transition-transform duration-200 ease-[cubic-bezier(0.32,0.72,0,1)] motion-reduce:transition-none",
                checked ? "scale-100" : "scale-0"
              )}
            />
          </span>
        }
      >
        {children}
      </ItemBody>
    </button>
  );
}

"use client";

import {
  forwardRef,
  useId,
  useImperativeHandle,
  useLayoutEffect,
  useRef,
  useState,
  type ChangeEvent,
  type InputHTMLAttributes,
  type ReactNode,
  type TextareaHTMLAttributes,
} from "react";
import { cn } from "@/lib/utils";

// Input, Textarea and Field in one. The control is a well cut into the surface; above it sits
// the label, below it a hint or, when something's wrong, the error. Every id and aria link is
// wired for you (label → control, control → hint/error, aria-invalid).
//
// `multiline` swaps the <input> for a <textarea> in the same well, optionally growing with its
// content. Single-line fields take a leading slot (an icon) and a trailing slot (text such as a
// unit, or an action); password fields get a show/hide toggle. With `maxLength`, a quiet counter
// keeps count. Focus brightens the edge and deepens the well one step. No glow.

export type TextFieldSize = "sm" | "md" | "lg";

interface TextFieldOwnProps {
  label?: ReactNode;
  /** Hint under the field. Replaced by `error` while there is one. */
  description?: ReactNode;
  /** An error message. Tints the edge, sets aria-invalid and shows in place of the hint. */
  error?: ReactNode;
  /** Height of a single-line field: 32, 40 or 48px. Default "md". */
  size?: TextFieldSize;
  /** A <textarea> instead of an <input>. */
  multiline?: boolean;
  /** Multiline only: grow with the content, up to `maxRows`. */
  autoResize?: boolean;
  /** Multiline only. Default 3. */
  rows?: number;
  /** Multiline + autoResize only. Default 10. */
  maxRows?: number;
  /** Single-line only: an icon or text inside the well, before the value. */
  leading?: ReactNode;
  /** Single-line only: text or an action inside the well, after the value. */
  trailing?: ReactNode;
  /** Show "12 / 200" under the field. Defaults to on when maxLength is set. */
  showCount?: boolean;
  /** Classes for the outer wrapper (label + well + message). */
  className?: string;
  /** Classes for the well itself. */
  fieldClassName?: string;
}

type Shared = "size" | "rows" | "prefix" | keyof TextFieldOwnProps;
export type TextFieldProps = TextFieldOwnProps &
  Omit<InputHTMLAttributes<HTMLInputElement>, Shared> &
  Omit<TextareaHTMLAttributes<HTMLTextAreaElement>, Shared | keyof InputHTMLAttributes<HTMLInputElement>>;

// Class names are written out in full so Tailwind can see them.
const SIZES: Record<TextFieldSize, { field: string; text: string; pad: string; pl: string; pr: string; slot: string }> = {
  sm: { field: "h-8 rounded-lg", text: "text-[13px]", pad: "px-2.5", pl: "pl-2.5", pr: "pr-2.5", slot: "[&_svg]:size-3.5" },
  md: { field: "h-10 rounded-xl", text: "text-sm", pad: "px-3", pl: "pl-3", pr: "pr-3", slot: "[&_svg]:size-4" },
  lg: { field: "h-12 rounded-xl", text: "text-[15px]", pad: "px-3.5", pl: "pl-3.5", pr: "pr-3.5", slot: "[&_svg]:size-[18px]" },
};

const WELL = cn(
  "relative flex w-full border bg-[#070707]",
  "shadow-[inset_0_1.5px_3px_rgba(0,0,0,0.85),0_1px_0_rgba(255,255,255,0.05)]",
  "transition-[border-color,background-color] duration-150",
  "has-[:focus]:bg-[#050505]"
);

export const TextField = forwardRef<HTMLInputElement & HTMLTextAreaElement, TextFieldProps>(function TextField(
  {
    label,
    description,
    error,
    size = "md",
    multiline = false,
    autoResize = false,
    rows = 3,
    maxRows = 10,
    leading,
    trailing,
    showCount,
    className,
    fieldClassName,
    id: idProp,
    type = "text",
    disabled,
    readOnly,
    required,
    maxLength,
    value,
    defaultValue,
    onChange,
    "aria-describedby": ariaDescribedBy,
    ...rest
  },
  ref
) {
  const autoId = useId();
  const id = idProp ?? autoId;
  const messageId = `${id}-message`;
  const countId = `${id}-count`;
  const invalid = Boolean(error);
  const message = error ?? description;
  const s = SIZES[size];

  const controlRef = useRef<HTMLInputElement & HTMLTextAreaElement>(null);
  useImperativeHandle(ref, () => controlRef.current as HTMLInputElement & HTMLTextAreaElement);

  // Track length for the counter (and for auto-resize), controlled or not.
  const [ownLength, setOwnLength] = useState(String(defaultValue ?? "").length);
  const length = value !== undefined ? String(value).length : ownLength;
  const counting = showCount ?? maxLength !== undefined;

  const [revealed, setRevealed] = useState(false);
  const isPassword = !multiline && type === "password";

  const handleChange = (event: ChangeEvent<HTMLInputElement & HTMLTextAreaElement>) => {
    if (value === undefined) setOwnLength(event.target.value.length);
    onChange?.(event);
  };

  // Auto-grow: measure the content height, clamp it between `rows` and `maxRows`.
  useLayoutEffect(() => {
    const el = controlRef.current;
    if (!multiline || !autoResize || !el) return;
    const style = window.getComputedStyle(el);
    const line = parseFloat(style.lineHeight) || 20;
    const chrome = parseFloat(style.paddingTop) + parseFloat(style.paddingBottom);
    el.style.height = "auto";
    const next = Math.min(Math.max(el.scrollHeight, line * rows + chrome), line * maxRows + chrome);
    el.style.height = `${next}px`;
    el.style.overflowY = el.scrollHeight > next ? "auto" : "hidden";
  }, [multiline, autoResize, rows, maxRows, length, value]);

  const describedBy = [message ? messageId : null, counting ? countId : null, ariaDescribedBy].filter(Boolean).join(" ") || undefined;

  const shared = {
    id,
    disabled,
    readOnly,
    required,
    maxLength,
    value,
    defaultValue,
    onChange: handleChange,
    "aria-invalid": invalid || undefined,
    "aria-describedby": describedBy,
  };

  const control = multiline ? (
    <textarea
      {...(rest as TextareaHTMLAttributes<HTMLTextAreaElement>)}
      {...shared}
      ref={controlRef}
      rows={rows}
      className={cn(
        "block w-full resize-none bg-transparent py-2.5 leading-relaxed tracking-tight text-neutral-100 outline-none placeholder:text-neutral-500",
        "[scrollbar-color:#2a2a2c_transparent] [scrollbar-width:thin] disabled:cursor-not-allowed",
        s.text,
        s.pad,
        !autoResize && "min-h-[inherit]"
      )}
    />
  ) : (
    <input
      {...(rest as InputHTMLAttributes<HTMLInputElement>)}
      {...shared}
      ref={controlRef}
      type={isPassword && revealed ? "text" : type}
      className={cn(
        "h-full min-w-0 flex-1 bg-transparent tracking-tight text-neutral-100 outline-none placeholder:text-neutral-500",
        "disabled:cursor-not-allowed [&::-webkit-search-cancel-button]:hidden",
        s.text,
        leading ? "pl-2" : s.pl,
        trailing || isPassword ? "pr-2" : s.pr
      )}
    />
  );

  return (
    <div
      data-invalid={invalid ? "" : undefined}
      data-disabled={disabled ? "" : undefined}
      className={cn("flex w-full flex-col gap-1.5", disabled && "opacity-40", className)}
    >
      {label && (
        <label htmlFor={id} className="flex items-baseline gap-1 text-sm font-medium tracking-tight text-neutral-100">
          {label}
          {required && (
            <span aria-hidden="true" className="text-neutral-500">
              *
            </span>
          )}
        </label>
      )}

      <div
        className={cn(
          WELL,
          multiline ? "rounded-xl" : cn(s.field, "items-center"),
          invalid
            ? "border-[rgb(229_115_115/0.45)]"
            : "border-white/[0.08] has-[:focus-visible]:border-white/[0.18] has-[:focus]:border-white/[0.18]",
          !disabled && !invalid && "hover:border-white/[0.13]",
          disabled && "cursor-not-allowed",
          readOnly && "bg-[#0a0a0b]",
          fieldClassName
        )}
      >
        {!multiline && leading && (
          <span className={cn("inline-flex shrink-0 items-center text-neutral-500", s.pl, s.text, s.slot)}>
            {leading}
          </span>
        )}
        {control}
        {!multiline && trailing && (
          <span className={cn("inline-flex shrink-0 items-center text-neutral-500", isPassword ? "pr-1" : s.pr, s.text, s.slot)}>
            {trailing}
          </span>
        )}
        {isPassword && (
          <button
            type="button"
            onClick={() => setRevealed((shown) => !shown)}
            aria-label={revealed ? "Hide password" : "Show password"}
            aria-pressed={revealed}
            disabled={disabled}
            className={cn(
              "mr-1 grid size-8 shrink-0 cursor-pointer place-items-center rounded-lg text-neutral-500",
              "transition-colors duration-150 hover:text-neutral-100",
              "outline-white/40 focus-visible:outline focus-visible:outline-1 disabled:cursor-not-allowed"
            )}
          >
            <svg viewBox="0 0 16 16" width="15" height="15" fill="none" aria-hidden="true">
              <path
                d="M1.5 8S3.8 3.5 8 3.5 14.5 8 14.5 8 12.2 12.5 8 12.5 1.5 8 1.5 8Z"
                stroke="currentColor"
                strokeWidth="1.4"
                strokeLinejoin="round"
              />
              <circle cx="8" cy="8" r="2" stroke="currentColor" strokeWidth="1.4" />
              {revealed && <path d="m2.5 13.5 11-11" stroke="currentColor" strokeWidth="1.4" strokeLinecap="round" />}
            </svg>
          </button>
        )}
      </div>

      {(message || counting) && (
        <div className="flex items-start justify-between gap-3">
          {message ? (
            <p
              id={messageId}
              className={cn("flex items-start gap-1.5 text-[13px] leading-snug", invalid ? "text-[rgb(229_115_115)]" : "text-neutral-500")}
            >
              {invalid && (
                <svg viewBox="0 0 16 16" width="13" height="13" fill="none" aria-hidden="true" className="mt-[2px] shrink-0">
                  <circle cx="8" cy="8" r="6.25" stroke="currentColor" strokeWidth="1.4" />
                  <path d="M8 4.75v3.75" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" />
                  <circle cx="8" cy="11" r="0.9" fill="currentColor" />
                </svg>
              )}
              <span>{message}</span>
            </p>
          ) : (
            <span />
          )}
          {counting && (
            <span
              id={countId}
              className={cn(
                "shrink-0 text-xs tabular-nums",
                maxLength !== undefined && length >= maxLength ? "text-neutral-300" : "text-neutral-600"
              )}
            >
              {maxLength !== undefined ? `${length} / ${maxLength}` : length}
            </span>
          )}
        </div>
      )}
    </div>
  );
});

import { clsx, type ClassValue } from "clsx";
import { twMerge } from "tailwind-merge";

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}
